    const NAMES = ['en' => 'English', 'cs' => 'čeština', 'de' => 'Deutsch', 'es' => 'español', 'fr' => 'français', 'pt' => 'português', 'it' => 'italiano', 'pl' => 'polski', 'nl' => 'Nederlands', 'uk' => 'українська', 'ar' => 'العربية', 'hi' => 'हिन्दी', 'zh' => '简体中文', 'ja' => '日本語', 'ko' => '한국어', 'tr' => 'Türkçe', 'id' => 'Bahasa Indonesia', 'ru' => 'русский'];

    public static function lang(?string $l, string $fallback = 'en'): string
    {
        $l = strtolower(substr((string) $l, 0, 2));
        return in_array($l, self::LANGS, true) ? $l : $fallback;
    }
    public static function get(string $lang, string $key, array $vars = [], array $over = []): string
    {
        $s = $over[$lang][$key] ?? self::T[$lang][$key] ?? self::T['en'][$key] ?? $key;
        foreach ($vars as $k => $v) $s = str_replace('{' . $k . '}', (string) $v, $s);
        return $s;
    }
}
